import React, { useEffect, useState } from 'react';
import { View, Text, TextInput, FlatList, Image, TouchableOpacity, StyleSheet, Dimensions } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { collection, onSnapshot, query, orderBy, doc } from 'firebase/firestore';
import { auth, db } from '../config';
import { useTheme, BRAND } from '../constants/theme';
import { SavedView } from '../constants/SavedView';

const W = Dimensions.get('window').width / 3 - 2;
const thumb = (p: any) => (p?.mediaType === 'video' && p?.mediaUrl ? p.mediaUrl.replace(/\.[^/.]+$/, '.jpg') : p?.mediaUrl);

export default function ExploreScreen() {
  const router = useRouter();
    const params = useLocalSearchParams<{ q?: string }>();
      const { c } = useTheme();
        const myUid = auth.currentUser?.uid || '';
          const [me, setMe] = useState<any>(null);
            const [searchMode, setSearchMode] = useState(false);
              const [savedMode, setSavedMode] = useState(false);
                const [search, setSearch] = useState(params.q || '');
                  const [history, setHistory] = useState<any[]>([]);
                    const [users, setUsers] = useState<any[]>([]);
                      const [posts, setPosts] = useState<any[]>([]);

                        useEffect(() => { if (params.q) { setSearch(params.q); setSearchMode(true); } }, [params.q]);

                          useEffect(() => {
                              AsyncStorage.getItem('flevora_recent').then((v) => { if (v) setHistory(JSON.parse(v)); });
                                  const u1 = onSnapshot(collection(db, 'users'), (s) => setUsers(s.docs.map((d) => ({ id: d.id, ...d.data() }))));
                                      const u2 = onSnapshot(query(collection(db, 'posts'), orderBy('createdAt', 'desc')), (s) => setPosts(s.docs.map((d) => ({ id: d.id, ...d.data() }))));
                                          const u3 = myUid ? onSnapshot(doc(db, 'users', myUid), (s) => { if (s.exists()) setMe(s.data()); }) : () => {};
                                              return () => { u1(); u2(); u3(); };
                                                }, [myUid]);

                                                  const addHistory = (item: { type: 'text' | 'user'; label: string; uid?: string; photoUrl?: string; name?: string }) => {
                                                      const next = [item, ...history.filter((h) => h.label !== item.label)].slice(0, 10);
                                                          setHistory(next);
                                                              AsyncStorage.setItem('flevora_recent', JSON.stringify(next));
                                                                };

                                                                  const removeHistory = (label: string) => {
                                                                      const next = history.filter((h) => h.label !== label);
                                                                          setHistory(next);
                                                                              AsyncStorage.setItem('flevora_recent', JSON.stringify(next));
                                                                                };

                                                                                  if (savedMode) {
                                                                                      return <SavedView myUid={myUid} me={me} posts={posts} c={c} onBack={() => setSavedMode(false)} onOpenReel={() => { setSavedMode(false); router.push('/reels'); }} />;
                                                                                        }

                                                                                          const q = search.trim().toLowerCase();
                                                                                            const matchedUsers = q ? users.filter((u) => (u.username || '').toLowerCase().includes(q) || (u.name || '').toLowerCase().includes(q)) : [];
                                                                                              const matchedReels = q ? posts.filter((p) => (p.caption || '').toLowerCase().includes(q) || (p.username || '').toLowerCase().includes(q) || (p.audioName || '').toLowerCase().includes(q)) : [];
                                                                                                const suggested = [...posts].sort((a, b) => (b.mediaType === 'video' ? 1 : 0) - (a.mediaType === 'video' ? 1 : 0) || (b.views || 0) - (a.views || 0));

                                                                                                  if (searchMode) {
                                                                                                      return (
                                                                                                            <View style={[s.wrap, { backgroundColor: c.background }]}>
                                                                                                                    <View style={s.sHdr}>
                                                                                                                              <TouchableOpacity onPress={() => { setSearchMode(false); setSearch(''); }}><Ionicons name="arrow-back" size={24} color={c.text} /></TouchableOpacity>
                                                                                                                                        <View style={[s.sBar, { backgroundColor: c.input, flex: 1 }]}>
                                                                                                                                                    <Ionicons name="search" size={18} color={c.muted} />
                                                                                                                                                                <TextInput autoFocus value={search} onChangeText={setSearch} onSubmitEditing={() => search.trim() && addHistory({ type: 'text', label: search.trim() })} placeholder="Search accounts, reels, songs..." placeholderTextColor={c.muted} style={[s.inp, { color: c.text }]} />
                                                                                                                                                                            {!!search && <TouchableOpacity onPress={() => setSearch('')}><Ionicons name="close-circle" size={18} color={c.muted} /></TouchableOpacity>}
                                                                                                                                                                                      </View>
                                                                                                                                                                                              </View>

                                                                                                                                                                                                      {!q ? (
                                                                                                                                                                                                                <FlatList
                                                                                                                                                                                                                            data={history} keyExtractor={(i) => i.label}
                                                                                                                                                                                                                                        ListHeaderComponent={
                                                                                                                                                                                                                                                      <View style={s.recHdr}>
                                                                                                                                                                                                                                                                      <Text style={{ fontWeight: '700', fontSize: 15, color: c.text }}>Recent</Text>
                                                                                                                                                                                                                                                                                      {history.length > 0 && <TouchableOpacity onPress={() => { setHistory([]); AsyncStorage.removeItem('flevora_recent'); }}><Text style={{ color: '#3B82F6', fontWeight: '600' }}>Clear all</Text></TouchableOpacity>}
                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                            renderItem={({ item }) => (
                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity style={s.recRow} onPress={() => item.type === 'user' && item.uid ? router.push(`/user/${item.uid}`) : setSearch(item.label)}>
                                                                                                                                                                                                                                                                                                                                                          {item.type === 'user' ? (item.photoUrl ? <Image source={{ uri: item.photoUrl }} style={s.av} /> : <View style={[s.av, s.ph]}><Ionicons name="person" size={18} color="#fff" /></View>) : <View style={[s.av, { backgroundColor: c.input, alignItems: 'center', justifyContent: 'center' }]}><Ionicons name="time-outline" size={20} color={c.text} /></View>}
                                                                                                                                                                                                                                                                                                                                                                          <View style={{ flex: 1 }}><Text style={{ fontWeight: '600', color: c.text }}>{item.label}</Text>{item.name ? <Text style={{ fontSize: 12, color: c.muted }}>{item.name}</Text> : null}</View>
                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity onPress={() => removeHistory(item.label)}><Ionicons name="close" size={18} color={c.muted} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                              />
                                                                                                                                                                                                                                                                                                                                                                                                                                      ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                <FlatList
                                                                                                                                                                                                                                                                                                                                                                                                                                                            data={[...matchedUsers.map((u) => ({ ...u, _k: 'u' })), ...matchedReels.map((p) => ({ ...p, _k: 'p' }))]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        keyExtractor={(i) => i._k + i.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    renderItem={({ item }: any) => item._k === 'u' ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity style={s.recRow} onPress={() => { addHistory({ type: 'user', label: item.username, uid: item.id, photoUrl: item.photoUrl, name: item.name }); router.push(`/user/${item.id}`); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {item.photoUrl ? <Image source={{ uri: item.photoUrl }} style={s.av} /> : <View style={[s.av, s.ph]}><Ionicons name="person" size={18} color="#fff" /></View>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View><Text style={{ fontWeight: '700', color: c.text }}>{item.username}</Text><Text style={{ fontSize: 12, color: c.muted }}>{item.name || 'Account'}</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity style={s.recRow} onPress={() => { addHistory({ type: 'text', label: item.caption || item.username }); router.push('/reels'); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Image source={{ uri: thumb(item) }} style={s.reelMini} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <View style={{ flex: 1 }}><Text style={{ fontWeight: '600', color: c.text }} numberOfLines={1}>{item.caption || 'Reel'}</Text><Text style={{ fontSize: 12, color: c.muted }}>@{item.username}{item.audioName ? ` · 🎵 ${item.audioName}` : ''}</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={[s.wrap, { backgroundColor: c.background }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={s.topRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity style={[s.sBar, { backgroundColor: c.input, flex: 1 }]} onPress={() => setSearchMode(true)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Ionicons name="search" size={18} color={c.muted} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Text style={{ color: c.muted, marginLeft: 8, fontSize: 15 }}>Search</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity onPress={() => setSavedMode(true)} style={{ padding: 4 }}><Ionicons name="bookmark-outline" size={25} color={c.text} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <FlatList
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              data={suggested} numColumns={3} keyExtractor={(i) => i.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      renderItem={({ item }) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <TouchableOpacity style={s.tile} onPress={() => router.push('/reels')}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Image source={{ uri: thumb(item) }} style={s.tileImg} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={s.views}><Ionicons name="eye-outline" size={13} color="#fff" /><Text style={{ color: '#fff', fontSize: 11, fontWeight: '700' }}>{item.views || item.likes?.length || 0}</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const s = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        wrap: { flex: 1, paddingTop: 44 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          topRow: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 14, paddingBottom: 10, gap: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sHdr: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 14, paddingBottom: 10, gap: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              sBar: { flexDirection: 'row', alignItems: 'center', borderRadius: 22, paddingHorizontal: 14, height: 40 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                inp: { flex: 1, marginLeft: 8, fontSize: 15 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  recHdr: { flexDirection: 'row', justifyContent: 'space-between', paddingHorizontal: 16, paddingVertical: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    recRow: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 9, gap: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      av: { width: 42, height: 42, borderRadius: 21 }, ph: { backgroundColor: BRAND, alignItems: 'center', justifyContent: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        reelMini: { width: 42, height: 52, borderRadius: 6 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          tile: { width: W, height: W * 1.38, margin: 1 }, tileImg: { width: '100%', height: '100%' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            views: { position: 'absolute', bottom: 6, left: 6, flexDirection: 'row', alignItems: 'center', gap: 4 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            